import { useMemo, useState } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import { Input } from "@/components/ui/input";
import { DashboardLayout } from "@/components/layout/DashboardLayout";
import { useDashboardStats } from "@/hooks/useDashboardStats";
import { useNavigate } from "react-router-dom";
import {
  Users,
  Calendar,
  DollarSign,
  Package,
  Clock,
  Plus,
  ClipboardList,
  Search,
  Copy,
  TrendingUp,
  AlertTriangle,
  Activity
} from "lucide-react";
import { DashboardAlerts } from "@/components/dashboard/DashboardAlerts";
import { toast } from "@/hooks/use-toast";
import { ETAPAS_PPR, TipoExecutor } from "@/types/procedimentos";
import { format } from "date-fns";
import { ptBR } from "date-fns/locale";
import { useProcedimentos } from '@/hooks/useProcedimentos';
import { useProcedimentosPTPM } from '@/hooks/useProcedimentosPTPM';
import { useProcedimentosFixa } from '@/hooks/useProcedimentosFixa';
import { useProcedimentosProtocolo } from '@/hooks/useProcedimentosProtocolo';
import { useResinaImpressa } from '@/hooks/useResinaImpressa';
import { useCeramica } from '@/hooks/useCeramica';
import { usePlaca } from '@/hooks/usePlaca';
import { useProvisorio } from '@/hooks/useProvisorio';
import { useLabExterno } from '@/hooks/useLabExterno';
import { usePerformanceStats } from "@/hooks/usePerformanceStats";

// Função para obter a última modificação de um procedimento
function getUltimaModificacao(proc: any): {
  etapaLabel: string;
  responsavel: TipoExecutor;
  executadoPor: string;
  executadoEm: string | null;
} | null {
  let ultimaData: Date | null = null;
  let ultimaEtapa: { label: string; responsavel: TipoExecutor } | null = null;
  let executadoPor = '';
  let executadoEm: string | null = null;

  for (const etapa of ETAPAS_PPR) {
    const executadoEmKey = `${etapa.key}_executado_em` as keyof typeof proc;
    const executadoPorKey = `${etapa.key}_executado_por` as keyof typeof proc;
    const dataExecucao = proc[executadoEmKey];

    if (dataExecucao) {
      const data = new Date(dataExecucao);
      if (!ultimaData || data > ultimaData) {
        ultimaData = data;
        ultimaEtapa = { label: etapa.label, responsavel: etapa.responsavel };
        executadoPor = proc[executadoPorKey] || '';
        executadoEm = dataExecucao;
      }
    }
  }

  if (ultimaEtapa) {
    return {
      etapaLabel: ultimaEtapa.label,
      responsavel: ultimaEtapa.responsavel,
      executadoPor,
      executadoEm,
    };
  }

  return null;
}

// Função para obter a cor baseada no responsável
function getCorResponsavelCard(responsavel: TipoExecutor): string {
  switch (responsavel) {
    case 'DENTISTA':
      return 'bg-blue-50 border-blue-300 text-blue-800';
    case 'PROTETICO':
      return 'bg-orange-50 border-orange-300 text-orange-800';
    case 'SECRETARIA':
      return 'bg-green-50 border-green-300 text-green-800';
    default:
      return 'bg-gray-50 border-gray-300 text-gray-800';
  }
}

// Função para obter a rota correta baseada no tipo do procedimento
function getRotaProcedimento(tipo: string, os: number): string {
  switch (tipo) {
    case 'PPR':
      return `/procedimentos/ppr/${os}`;
    case 'PT/PM':
      return `/procedimentos/pt-pm/${os}`;
    case 'FIXA ORTOVITAL':
      return `/procedimentos/fixa/${os}`;
    case 'PROTOCOLO PROVISORIO':
      return `/procedimentos/protocolo-provisorio/${os}`;
    case 'PROTOCOLO DEFINITIVO':
      return `/procedimentos/protocolo-definitivo/${os}`;
    case 'RESINA IMPRESSA':
      return `/procedimentos/resina-impressa/${os}`;
    case 'CERAMICA ORTOVITAL':
      return `/procedimentos/ceramica/${os}`;
    case 'PLACA DE BRUXISMO/CLAREAMENTO':
      return `/procedimentos/placa/${os}`;
    case 'PROVISORIO/ADESIVA':
      return `/procedimentos/provisorio/${os}`;
    case 'LAB EXTERNO':
      return `/procedimentos/lab-externo/${os}`;
  }
}

// Sub-componente para listas de OS no Dashboard
function OSList({ procs, onNavigate, emptyLabel, isAtrasadaList }: { 
  procs: any[], 
  onNavigate: (tipo: string, os: number) => void, 
  emptyLabel: string,
  isAtrasadaList?: boolean 
}) {
  if (procs.length === 0) {
    return (
      <div className="text-center py-12 bg-muted/10 rounded-xl border-2 border-dashed">
        <ClipboardList className="w-10 h-10 mx-auto text-muted-foreground opacity-20 mb-3" />
        <p className="text-sm font-medium text-muted-foreground">{emptyLabel}</p>
      </div>
    );
  }

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
      {procs.slice(0, 10).map(proc => (
        <div 
          key={proc.id} 
          onClick={() => onNavigate(proc.tipo, proc.ordem_servico)}
          className={`p-4 border-2 rounded-xl bg-white hover:shadow-lg transition-all cursor-pointer group ${isAtrasadaList ? 'border-red-100 hover:border-red-300' : 'border-border/50 hover:border-primary/30'}`}
        >
          <div className="flex justify-between items-start mb-2">
            <span className={`text-[10px] font-black px-2 py-0.5 rounded-full uppercase tracking-tighter ${isAtrasadaList ? 'bg-red-50 text-red-600' : 'bg-muted text-muted-foreground'}`}>
              OS #{proc.ordem_servico.toString().padStart(6, '0')}
            </span>
            <Badge variant="outline" className={`text-[10px] font-bold uppercase ${isAtrasadaList ? 'border-red-200 text-red-700 bg-red-50' : ''}`}>
              {proc.tipo}
            </Badge>
          </div>
          <p className="font-bold text-gray-900 group-hover:text-primary transition-colors truncate text-base">{proc.nome_paciente}</p>
          <div className="flex justify-between items-center mt-3 pt-3 border-t border-dashed border-border">
            <div className="flex flex-col">
              <span className="text-[10px] font-bold text-muted-foreground uppercase opacity-70">Entrega</span>
              <span className={`text-xs font-black ${isAtrasadaList ? 'text-red-600 animate-pulse' : 'text-gray-700'}`}>
                {proc.data_entrega && !isNaN(new Date(proc.data_entrega).getTime()) 
                  ? format(new Date(proc.data_entrega), 'dd/MM/yyyy', { locale: ptBR }) 
                  : 'N/D'}
              </span>
            </div>
            <Badge variant="outline" className={`text-[10px] font-extrabold ${
              proc.status_geral === 'Pendente' ? 'bg-yellow-50 text-yellow-700 border-yellow-300' : 
              proc.status_geral === 'Concluído' ? 'bg-green-50 text-green-700 border-green-300' : 
              'bg-blue-50 text-blue-700 border-blue-300'
            }`}>
              {proc.status_geral.toUpperCase()}
            </Badge>
          </div>
        </div>
      ))}
    </div>
  );
}

export default function Dashboard() {
  const navigate = useNavigate();
  const { stats, proximosAgendamentos, isLoading } = useDashboardStats();
  const { data: performance, isLoading: loadingPerformance } = usePerformanceStats();
  const [subTabAtiva, setSubTabAtiva] = useState<string>('todos-tipos');
  const [buscaRapida, setBuscaRapida] = useState<string>('');

  // Buscar todos os tipos de procedimentos
  const { data: procedimentosPPR } = useProcedimentos();
  const { data: procedimentosPTPM } = useProcedimentosPTPM();
  const { data: procedimentosFixa } = useProcedimentosFixa();
  const { data: procedimentosProtocolo } = useProcedimentosProtocolo();
  const { data: procedimentosResinaImpressa } = useResinaImpressa();
  const { data: procedimentosCeramica } = useCeramica();
  const { data: procedimentosPlaca } = usePlaca();
  const { data: procedimentosProvisorio } = useProvisorio();
  const { data: procedimentosLabExterno } = useLabExterno();

  // Combinar todos os procedimentos
  const todosProcedimentos = useMemo(() => {
    const ppr = (procedimentosPPR || []).map((p: any) => ({ ...p, tipo: 'PPR' }));
    const ptpm = (procedimentosPTPM || []).map((p: any) => ({ ...p, tipo: 'PT/PM' }));
    const fixa = (procedimentosFixa || []).map((p: any) => ({ ...p, tipo: 'FIXA ORTOVITAL' }));
    const protocoloProvisorio = (procedimentosProtocolo?.filter((p: any) => p.tipo_protocolo === 'PROVISORIO') || []).map((p: any) => ({ ...p, tipo: 'PROTOCOLO PROVISORIO' }));
    const protocoloDefinitivo = (procedimentosProtocolo?.filter((p: any) => p.tipo_protocolo === 'DEFINITIVO') || []).map((p: any) => ({ ...p, tipo: 'PROTOCOLO DEFINITIVO' }));
    const resinaImpressa = (procedimentosResinaImpressa || []).map((p: any) => ({ ...p, tipo: 'RESINA IMPRESSA' }));
    const ceramica = (procedimentosCeramica || []).map((p: any) => ({ ...p, tipo: 'CERAMICA ORTOVITAL' }));
    const placa = (procedimentosPlaca || []).map((p: any) => ({ ...p, tipo: 'PLACA DE BRUXISMO/CLAREAMENTO' }));
    const provisorio = (procedimentosProvisorio || []).map((p: any) => ({ ...p, tipo: 'PROVISORIO/ADESIVA' }));
    const labExterno = (procedimentosLabExterno || []).map((p: any) => ({ ...p, tipo: 'LAB EXTERNO' }));
    return [...ppr, ...ptpm, ...fixa, ...protocoloProvisorio, ...protocoloDefinitivo, ...resinaImpressa, ...ceramica, ...placa, ...provisorio, ...labExterno];
  }, [procedimentosPPR, procedimentosPTPM, procedimentosFixa, procedimentosProtocolo, procedimentosResinaImpressa, procedimentosCeramica, procedimentosPlaca, procedimentosProvisorio, procedimentosLabExterno]);

  // Função para copiar OS para clipboard
  const copiarOS = (os: number, e: React.MouseEvent) => {
    e.stopPropagation();
    navigator.clipboard.writeText(os.toString());
    toast({
      title: "OS Copiada!",
      description: `OS #${os} copiada para a área de transferência`,
    });
  };

  // Contar procedimentos por tipo
  const contadoresPorTipo = useMemo(() => {
    const contadores: { [key: string]: number } = {
      'todos-tipos': todosProcedimentos?.length || 0,
      'PPR': 0,
      'PT/PM': 0,
      'FIXA ORTOVITAL': 0,
      'PROTOCOLO PROVISORIO': 0,
      'PROTOCOLO DEFINITIVO': 0,
      'RESINA IMPRESSA': 0,
      'CERAMICA ORTOVITAL': 0,
      'PLACA DE BRUXISMO/CLAREAMENTO': 0,
      'PROVISORIO/ADESIVA': 0,
      'LAB EXTERNO': 0,
    };

    todosProcedimentos?.forEach((p: any) => {
      if (contadores[p.tipo] !== undefined) {
        contadores[p.tipo]++;
      }
    });

    return contadores;
  }, [todosProcedimentos]);

  // Filtrar procedimentos por sub-aba
  const procedimentosFiltradosPorTipo = useMemo(() => {
    if (subTabAtiva === 'todos-tipos') {
      return todosProcedimentos;
    }
    return todosProcedimentos?.filter((p: any) => p.tipo === subTabAtiva) || [];
  }, [todosProcedimentos, subTabAtiva]);

  // Filtrar por busca rápida
  const procedimentosFiltradosPorBusca = useMemo(() => {
    if (!buscaRapida.trim()) {
      return procedimentosFiltradosPorTipo;
    }

    const termoBusca = buscaRapida.toLowerCase();
    return procedimentosFiltradosPorTipo?.filter((p: any) =>
      p.nome_paciente?.toLowerCase().includes(termoBusca) ||
      p.ordem_servico?.toString().includes(termoBusca)
    ) || [];
  }, [procedimentosFiltradosPorTipo, buscaRapida]);

  // Filtrar e ordenar procedimentos por última modificação (Últimas Atualizações)
  const ultimasOSModificadas = useMemo(() => {
    const filtered = procedimentosFiltradosPorBusca?.filter(
      p => p.status_geral === 'Em andamento' || p.status_geral === 'Pendente' || p.status_geral === 'Concluído'
    ) || [];

    // Pegar as com atualização real
    const comAtualizacao = filtered.filter(p => getUltimaModificacao(p)?.executadoEm != null);

    return comAtualizacao.sort((a, b) => {
      const ultimaA = getUltimaModificacao(a);
      const ultimaB = getUltimaModificacao(b);
      return new Date(ultimaB!.executadoEm!).getTime() - new Date(ultimaA!.executadoEm!).getTime();
    }).slice(0, 10);
  }, [procedimentosFiltradosPorBusca]);

  // Últimas OS Feitas (Abertas recentemente)
  const ultimasOSAbertas = useMemo(() => {
    const filtered = procedimentosFiltradosPorBusca || [];
    return [...filtered].sort((a, b) => b.ordem_servico - a.ordem_servico).slice(0, 10);
  }, [procedimentosFiltradosPorBusca]);

  // OS em Andamento (Filtro explícito)
  const osEmAndamentoFiltro = useMemo(() => {
    const filtered = procedimentosFiltradosPorBusca || [];
    return filtered.filter(p => p.status_geral === 'Em andamento' || p.status_geral === 'Pendente');
  }, [procedimentosFiltradosPorBusca]);

  // OS Atrasadas (Filtro explícito)
  const osAtrasadasFiltro = useMemo(() => {
    const filtered = procedimentosFiltradosPorBusca || [];
    const hoje = new Date();
    hoje.setHours(0, 0, 0, 0);

    return filtered.filter(p => {
      if (p.status_geral === 'Concluído') return false;
      if (!p.data_entrega) return false;
      return new Date(p.data_entrega) < hoje;
    });
  }, [procedimentosFiltradosPorBusca]);

  const statsCards = [
    {
      title: "Agendamentos Hoje",
      value: stats.agendamentosHoje.total.toString(),
      change: `${stats.agendamentosHoje.confirmados} confirmados, ${stats.agendamentosHoje.pendentes} pendentes`,
      icon: Calendar,
      color: "text-blue-600",
      bgColor: "bg-blue-50",
      borderColor: "border-blue-100"
    },
    {
      title: "OS em Andamento",
      value: stats.osEmAndamento.toString(),
      change: "Pendente ou em execução",
      icon: Activity,
      color: "text-indigo-600",
      bgColor: "bg-indigo-50",
      borderColor: "border-indigo-100"
    },
    {
      title: "OS Atrasadas",
      value: stats.osAtrasadas.toString(),
      change: stats.osAtrasadas > 0 ? "Ação imediata necessária" : "Tudo no prazo",
      icon: AlertTriangle,
      color: stats.osAtrasadas > 0 ? "text-red-600" : "text-emerald-600",
      bgColor: stats.osAtrasadas > 0 ? "bg-red-50" : "bg-emerald-50",
      borderColor: stats.osAtrasadas > 0 ? "border-red-100" : "border-emerald-100"
    },
    {
      title: "Faturamento Mensal",
      value: new Intl.NumberFormat("pt-BR", {
        style: "currency",
        currency: "BRL",
      }).format(stats.faturamentoMensal),
      change: `Previsto: ${new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" }).format(stats.faturamentoPrevisto)}`,
      icon: TrendingUp,
      color: "text-emerald-600",
      bgColor: "bg-emerald-50",
      borderColor: "border-emerald-100"
    },
  ];

  return (
    <DashboardLayout>
      <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl sm:text-3xl font-bold text-foreground">Dashboard</h1>
          <p className="text-muted-foreground">
            Bem-vindo ao seu sistema de gestão odontológica
          </p>
        </div>
        <div className="flex flex-col sm:flex-row gap-3 w-full sm:w-auto">
          <Button
            variant="outline"
            className="w-full sm:w-auto border-2 hover:border-primary hover:bg-primary/5"
            onClick={() => navigate("/procedimentos")}
          >
            <ClipboardList className="w-4 h-4 mr-2" />
            Procedimentos
          </Button>
          <Button
            variant="medical"
            className="w-full sm:w-auto"
            onClick={() => navigate("/appointments")}
          >
            <Plus className="w-4 h-4 mr-2" />
            Nova Consulta
          </Button>
        </div>
      </div>

      {/* Alerts Section */}
      <DashboardAlerts stats={stats} isLoading={isLoading} />

      {/* Stats Cards */}
      <div className="grid gap-4 sm:gap-6 grid-cols-1 sm:grid-cols-2 lg:grid-cols-4">
        {isLoading ? (
          <>
            {[1, 2, 3, 4].map((i) => (
              <Card key={i} className="medical-card">
                <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                  <Skeleton className="h-4 w-24" />
                  <Skeleton className="h-4 w-4 rounded-full" />
                </CardHeader>
                <CardContent>
                  <Skeleton className="h-8 w-16 mb-2" />
                  <Skeleton className="h-3 w-32" />
                </CardContent>
              </Card>
            ))}
          </>
        ) : (
          statsCards.map((stat) => (
            <Card key={stat.title} className={`medical-card border-2 ${stat.borderColor} hover:shadow-md transition-all`}>
              <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                <CardTitle className="text-sm font-bold text-gray-600">{stat.title}</CardTitle>
                <div className={`p-2 rounded-lg ${stat.bgColor}`}>
                  <stat.icon className={`h-4 w-4 ${stat.color}`} />
                </div>
              </CardHeader>
              <CardContent>
                <div className="text-2xl font-black text-gray-800">{stat.value}</div>
                <p className="text-xs font-medium text-muted-foreground mt-1">{stat.change}</p>
              </CardContent>
            </Card>
          ))
        )}
      </div>

      {/* Main Content Grid */}
      <div className="grid gap-6 lg:grid-cols-12">
        {/* Column 1: Today's Agenda (4/12) */}
        <div className="lg:col-span-4 lg:sticky lg:top-24 max-h-[calc(100vh-140px)]">
          <Card className="medical-card h-full flex flex-col">
            <CardHeader className="flex-shrink-0">
              <CardTitle className="flex items-center text-lg">
                <Calendar className="w-5 h-5 mr-2 text-primary" />
                Agenda de Hoje
              </CardTitle>
              <CardDescription>
                Consultas confirmadas para hoje
              </CardDescription>
            </CardHeader>
            <CardContent className="flex-1 overflow-y-auto px-4 pb-4">
              {isLoading ? (
                <div className="space-y-4">
                  {[1, 2, 3].map((i) => (
                    <Skeleton key={i} className="h-20 w-full rounded-xl" />
                  ))}
                </div>
              ) : proximosAgendamentos.length === 0 ? (
                <div className="text-center py-12 text-muted-foreground bg-muted/20 rounded-xl border-2 border-dashed">
                  <Clock className="w-10 h-10 mx-auto mb-3 opacity-20" />
                  <p className="text-sm font-medium">Agenda livre hoje</p>
                </div>
              ) : (
                <div className="space-y-3">
                  {proximosAgendamentos.map((appointment) => (
                    <div
                      key={appointment.id}
                      className="p-3 border-2 border-border/50 rounded-xl bg-white hover:bg-muted/30 hover:border-primary/30 transition-all group"
                    >
                      <div className="flex items-center justify-between mb-2">
                        <div className="flex items-center gap-2">
                          <div className="w-8 h-8 rounded-full bg-primary/10 flex items-center justify-center text-primary font-bold text-xs">
                            {appointment.time.split(':')[0]}
                          </div>
                          <span className="font-bold text-sm text-gray-700">{appointment.time}</span>
                        </div>
                        <Badge variant={appointment.status === "Confirmado" ? "default" : "secondary"} className="text-[10px] font-bold">
                          {appointment.status.toUpperCase()}
                        </Badge>
                      </div>
                      <p className="font-bold text-gray-900 group-hover:text-primary transition-colors truncate">{appointment.patient}</p>
                      <p className="text-xs text-muted-foreground mt-0.5 line-clamp-1">{appointment.procedure}</p>
                    </div>
                  ))}
                  <Button
                    variant="ghost"
                    className="w-full mt-4 text-xs font-bold text-primary hover:bg-primary/5 uppercase tracking-wider"
                    onClick={() => navigate("/appointments")}
                  >
                    Ver Agenda Completa
                  </Button>
                </div>
              )}
            </CardContent>
          </Card>
        </div>

        {/* Column 2: Dashboard Content Central (8/12) */}
        <div className="lg:col-span-8 flex flex-col gap-6">
          <Card className="medical-card border-l-4 border-l-primary shadow-lg overflow-hidden">
            <CardHeader className="pb-0 border-b-0">
              <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
                <div>
                  <CardTitle className="flex items-center text-xl font-black text-gray-800">
                    <Activity className="w-6 h-6 mr-2 text-primary" />
                    Gestão de Ordens de Serviço
                  </CardTitle>
                  <CardDescription className="text-sm font-medium mt-1">
                    Histórico, acompanhamento e status de produção
                  </CardDescription>
                </div>

                <div className="relative w-full sm:w-64">
                  <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-muted-foreground w-4 h-4" />
                  <Input 
                    placeholder="Filtrar OS ou Paciente..." 
                    className="pl-10 h-10 bg-muted/30 border-2 focus-visible:ring-primary/20"
                    value={buscaRapida}
                    onChange={(e) => setBuscaRapida(e.target.value)}
                  />
                </div>
              </div>
            </CardHeader>

            <CardContent className="pt-6">
              <Tabs defaultValue="recentes" className="w-full">
                <TabsList className="grid w-full grid-cols-2 md:grid-cols-4 h-auto p-1 bg-muted/40 rounded-xl mb-6">
                  <TabsTrigger value="recentes" className="py-2.5 font-bold data-[state=active]:bg-white data-[state=active]:shadow-sm rounded-lg flex items-center gap-2">
                    <Plus className="w-4 h-4" /> Recentes
                  </TabsTrigger>
                  <TabsTrigger value="andamento" className="py-2.5 font-bold data-[state=active]:bg-white data-[state=active]:shadow-sm rounded-lg flex items-center gap-2">
                    <Activity className="w-4 h-4" /> Em Produção
                  </TabsTrigger>
                  <TabsTrigger value="atrasadas" className="py-2.5 font-bold data-[state=active]:bg-white data-[state=active]:shadow-sm rounded-lg flex items-center gap-2">
                    <AlertTriangle className="w-4 h-4" /> {osAtrasadasFiltro.length > 0 && <span className="w-2 h-2 rounded-full bg-red-500 animate-pulse"></span>}Atrasadas
                  </TabsTrigger>
                  <TabsTrigger value="movimentacoes" className="py-2.5 font-bold data-[state=active]:bg-white data-[state=active]:shadow-sm rounded-lg flex items-center gap-2">
                    <TrendingUp className="w-4 h-4" /> Updates
                  </TabsTrigger>
                </TabsList>

                {/* Lists Content */}
                <div className="min-h-[450px] max-h-[600px] overflow-y-auto px-1">
                  <TabsContent value="recentes" className="m-0 focus-visible:ring-0">
                    <OSList procs={ultimasOSAbertas} onNavigate={(tipo, os) => navigate(getRotaProcedimento(tipo, os))} emptyLabel="Nenhuma OS aberta recentemente." />
                  </TabsContent>

                  <TabsContent value="andamento" className="m-0 focus-visible:ring-0">
                    <OSList procs={osEmAndamentoFiltro} onNavigate={(tipo, os) => navigate(getRotaProcedimento(tipo, os))} emptyLabel="Nenhuma OS em andamento no momento." />
                  </TabsContent>

                  <TabsContent value="atrasadas" className="m-0 focus-visible:ring-0">
                    <OSList procs={osAtrasadasFiltro} onNavigate={(tipo, os) => navigate(getRotaProcedimento(tipo, os))} emptyLabel="Parabéns! Nenhuma OS atrasada no momento." isAtrasadaList={true} />
                  </TabsContent>

                  <TabsContent value="movimentacoes" className="m-0 focus-visible:ring-0">
                     <div className="space-y-3">
                        {ultimasOSModificadas.map((proc) => {
                          const ultimaModificacao = getUltimaModificacao(proc);
                          return (
                            <div
                              key={proc.id}
                              className="p-4 border-2 border-border/50 rounded-xl bg-white hover:shadow-md hover:border-blue-300 transition-all cursor-pointer group"
                              onClick={() => navigate(getRotaProcedimento(proc.tipo, proc.ordem_servico))}
                            >
                              <div className="flex items-start justify-between mb-3">
                                <div>
                                  <span className="text-[10px] font-black text-blue-600 bg-blue-50 px-2 py-0.5 rounded-full uppercase tracking-tighter">
                                    OS #{proc.ordem_servico.toString().padStart(6, '0')}
                                  </span>
                                  <p className="font-bold text-gray-900 group-hover:text-primary transition-colors text-base mt-1">{proc.nome_paciente}</p>
                                </div>
                                <Badge variant="outline" className="text-[10px] border-blue-200 text-blue-800 bg-blue-50 font-bold uppercase">{proc.tipo}</Badge>
                              </div>

                              {ultimaModificacao && (
                                <div className={`p-3 rounded-lg border-2 ${getCorResponsavelCard(ultimaModificacao.responsavel)}`}>
                                  <div className="flex items-center justify-between">
                                    <div>
                                      <p className="font-black text-xs uppercase tracking-wide">{ultimaModificacao.etapaLabel}</p>
                                      <p className="text-[11px] mt-1 text-inherit opacity-80">
                                        Responsável: <span className="font-bold">{ultimaModificacao.executadoPor}</span>
                                      </p>
                                    </div>
                                    <div className="text-right">
                                      <p className="text-[10px] font-bold opacity-75">ATUALIZADO EM:</p>
                                      <p className="text-[11px] font-black">
                                        {!isNaN(new Date(ultimaModificacao.executadoEm!).getTime()) ? format(new Date(ultimaModificacao.executadoEm!), "dd/MM 'às' HH:mm", { locale: ptBR }) : ''}
                                      </p>
                                    </div>
                                  </div>
                                </div>
                              )}
                            </div>
                          );
                        })}
                     </div>
                  </TabsContent>
                </div>
              </Tabs>

            {/* Ranking de Produtividade (NOVO) */}
            <Card className="border-2 shadow-lg hover:shadow-xl transition-all duration-300 overflow-hidden">
              <CardHeader className="bg-gradient-to-r from-blue-50 to-transparent border-b">
                <CardTitle className="text-xl flex items-center gap-3">
                  <div className="p-2 bg-blue-500 rounded-lg">
                    <TrendingUp className="w-5 h-5 text-white" />
                  </div>
                  Performance do Mês
                </CardTitle>
                <CardDescription>
                  Profissionais com mais Ordens de Serviço concluídas.
                </CardDescription>
              </CardHeader>
              <CardContent className="pt-6">
                <div className="flex flex-col lg:flex-row gap-8">
                  {/* Dentistas Ranking */}
                  <div className="flex-1">
                    <h5 className="text-[10px] uppercase font-black text-blue-600 tracking-wider mb-3 flex items-center gap-2">
                      <div className="w-1.5 h-1.5 rounded-full bg-blue-500"></div>
                      Dentistas
                    </h5>
                    <div className="space-y-2 mt-4 min-h-[160px]">
                      {loadingPerformance ? (
                        Array(3).fill(0).map((_, i) => (
                          <div key={i} className="flex items-center gap-3 p-3 rounded-xl bg-gray-50/50">
                            <Skeleton className="w-8 h-8 rounded-full" />
                            <Skeleton className="h-4 flex-1" />
                            <Skeleton className="w-12 h-4" />
                          </div>
                        ))
                      ) : (performance?.dentistas || []).length > 0 ? (
                        performance.dentistas.slice(0, 3).map((d: any, i: number) => (
                          <div key={d.id} className="flex items-center justify-between p-3 rounded-xl bg-blue-50 border border-blue-100 hover:bg-blue-100 transition-colors">
                            <div className="flex items-center gap-3">
                              <div className={`w-8 h-8 rounded-full flex items-center justify-center font-bold text-sm ${i === 0 ? 'bg-blue-200 text-blue-800' : 'bg-gray-200 text-gray-600'}`}>
                                {i + 1}º
                              </div>
                              <span className="font-bold text-gray-800">{d.nome}</span>
                            </div>
                            <Badge variant="secondary" className="font-black text-blue-700">
                              {d.totalConcluido} OS
                            </Badge>
                          </div>
                        ))
                      ) : (
                        <p className="text-xs text-muted-foreground text-center py-8 italic">Nenhum dado este mês</p>
                      )}
                    </div>
                  </div>

                  {/* Protéticos Ranking */}
                  <div className="flex-1">
                    <h5 className="text-[10px] uppercase font-black text-orange-600 tracking-wider mb-3 flex items-center gap-2">
                      <div className="w-1.5 h-1.5 rounded-full bg-orange-500"></div>
                      Protéticos / Interno
                    </h5>
                    <div className="space-y-2 mt-4 min-h-[160px]">
                      {loadingPerformance ? (
                        Array(3).fill(0).map((_, i) => (
                          <div key={i} className="flex items-center gap-3 p-3 rounded-xl bg-gray-50/50">
                            <Skeleton className="w-8 h-8 rounded-full" />
                            <Skeleton className="h-4 flex-1" />
                            <Skeleton className="w-12 h-4" />
                          </div>
                        ))
                      ) : (performance?.proteticos || []).length > 0 ? (
                        performance.proteticos.slice(0, 3).map((p: any, i: number) => (
                          <div key={p.id} className="flex items-center justify-between p-3 rounded-xl bg-orange-50 border border-orange-100 hover:bg-orange-100 transition-colors">
                            <div className="flex items-center gap-3">
                              <div className={`w-8 h-8 rounded-full flex items-center justify-center font-bold text-sm ${i === 0 ? 'bg-orange-200 text-orange-800' : 'bg-gray-200 text-gray-600'}`}>
                                {i + 1}º
                              </div>
                              <span className="font-bold text-gray-800">{p.nome}</span>
                            </div>
                            <Badge variant="secondary" className="font-black text-orange-700">
                              {p.totalConcluido} OS
                            </Badge>
                          </div>
                        ))
                      ) : (
                        <p className="text-xs text-muted-foreground text-center py-8 italic">Nenhum dado este mês</p>
                      )}
                    </div>
                  </div>
                </div>
              </CardContent>
            </Card>

            {/* Opções de OS */}
            <div className="mt-6 flex justify-center">
              <Button variant="outline" className="text-xs font-bold uppercase border-2 hover:bg-muted/50" onClick={() => navigate('/procedimentos/consulta')}>
                Acessar Filtro Universal de OS
              </Button>
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  </div>
</DashboardLayout>
);
}
